}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// Cosmos DB context with fixes for EF Core 9 breaking changes
class CosmosDbContext : DbContext
{
    public DbSet<Document> Documents => Set<Document>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking Change #1: EF Core 9 renamed "Discriminator" -> "$type" for Cosmos.
        // To keep compatibility with existing documents that use "Discriminator",
        // explicitly configure the discriminator property name.
        modelBuilder.Entity<Document>()
            .HasDiscriminator<string>("Discriminator");

        // Breaking Change #2: EF Core 9 requires hierarchical partition keys
        // to be explicitly configured if using them. Ensure partition key is set.
        modelBuilder.Entity<Document>()
            .HasPartitionKey(d => d.PartitionKey);
    }

    // Breaking Change #3: Synchronous I/O is no longer supported on Cosmos provider
    // in EF Core 9. All queries must use async methods (ToListAsync, FirstAsync, etc.)
    public async Task<List<Document>> GetDocumentsAsync(string partitionKey)
    {
        // WRONG in EF9: Documents.Where(...).ToList()  — throws InvalidOperationException
        // CORRECT: use async
        return await Documents
            .Where(d => d.PartitionKey == partitionKey)
            .ToListAsync();
    }
}

class Document
{
    public string Id { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
    public string Content { get; set; } = default!;
}

