using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // Breaking Change #4: EF Core 9 throws if you call Migrate() inside a
    // manual transaction because migrations manage their own transactions.
    // Remove the wrapping transaction.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

